import { readFile, writeFile } from 'node:fs/promises';
const root = new URL('../', import.meta.url);
const files = ['server.js','media.js','combined-video.js','official-video.js','auth.js','package.json','public/index.html','public/app.js','public/audio-retry.js','public/audio-focus.js','public/media-controls.js','public/car-mode.css','capacitor.config.json','public/account.js','public/video-player.js','public/premium.css','scripts/brand-icons.js','scripts/rebrand.js','public/styles.css','public/tokens.css','public/manifest.json','public/service-worker.js','api/index.js','functions/api/[[path]].js','functions/auth/[[path]].js','render.yaml','vercel.json','Dockerfile','iniciar.ps1','scripts/build.js','scripts/assets.js','scripts/vendor.js','scripts/version-assets.js','scripts/live-check.js','test/review-regressions.test.js','test/account-dom.test.js','test/car-media.test.js','test/official-video.test.js','test/video-player.test.js','test/combined-video.test.js','test/media.test.js','test/server.test.js','test/audio-retry.test.js','test/auth.test.js','test/service-worker.test.js'];
let body='# Código-fonte — Fckyoutube 2.0.0\n\nApp-v7.js e styles-v3.css são cópias geradas pelo build. O player Shaka de terceiros e sua licença ficam em public/vendor.\n';
for (const file of files) body+=`\n## ${file}\n\n\`\`\`\n${await readFile(new URL(file,root),'utf8')}\n\`\`\`\n`;
await writeFile(new URL('CODIGO_COMPLETO.md',root),body);
